mapper.select:
-- 这里查找出来的字段为OrderShowVO字段，别名为了能够匹配上 SELECT orders.id, address_pick_up.address AS pick_up_address, -- 取件地址，字符串，类似：浙大城市学院 南校区 寝室楼 弘毅楼 寝室楼下 address_recive.address AS recive_address, -- 收件地址，字符串，类似：浙大城市学院 南校区 寝室楼 弘毅楼 寝室楼下 orders.order_number, orders.price, orders.service_fee_rate, orders.service_fee, orders.pay_amount, orders.real_price, orders.delivery_time, orders.cancel_time , orders.cancel_reson, orders.exceed_time, orders.gap, orders.create_time, orders.door_access, orders.user_id, orders.username, orders.phone, orders.status, orders.note, orders.image, category.image AS category_image, -- 类别图片路径，从类别表里得到 category.category_name, orders.deleted FROM tb_orders AS orders, -- 这是订单表 主表 tb_category AS category, -- 这是类别表 为了获得类别的图片, 即category_image (SELECT ad.id, CONCAT(school.school_name, ' ', compus.compus_name, ' ', build_category.name, ' ', building.building_name, ' ', ad.details) AS address -- 将查找出来的名字拼接成地址，用空格隔开 FROM tb_address_book AS ad, tb_school AS school, tb_compus AS compus, tb_build_category AS build_category, tb_building AS building
-- 这三张表保存这三个信息，需要读取 ad.school_id = school.id AND ad.compus_id = compus.id AND ad.build_category_id = build_category.id AND ad.building_id = building.id AND ad.deleted = 0 -- 这里主要是为了防止没有ids导致报错
and ad.id in
#{id}
) AS address_pick_up, -- 这张表类似视图，主要是为了获取地址的名字，address拼接后就是地址名字，这里获取了取件地址的详细信息 -- 对于按照取件地址查询筛选来说，取件地址这张'表',即address_pick_up应该将地址id作为条件查询
(SELECT ad.id, CONCAT(school.school_name, ' ', compus.compus_name, ' ', build_category.name, ' ', building.building_name, ' ', ad.details) AS address -- 将查找出来的名字拼接成地址，用空格隔开 FROM tb_address_book AS ad, tb_school AS school, tb_compus AS compus, tb_build_category AS build_category, tb_building AS building
ad.school_id = school.id AND ad.compus_id = compus.id AND ad.build_category_id = build_category.id AND ad.building_id = building.id AND ad.deleted = 0
) AS address_recive -- 这张表类似上面这张表，主要是为了获取地址的名字，address拼接后就是地址名字，这里获取了收件地址的详细信息 -- 不过对于按照取件地址查询来说，收件地址'表'，即address_recive应该不用约束地查
WHERE orders.deleted = 0 AND orders.status = 0 AND orders.category_id = category.id AND orders.pick_up_address = address_pick_up.id AND orders.recive_address = address_recive.id
AND orders.pick_up_address in
#{id}
ORDER BY orders.create_time desc

-- 以下SQL语句类似上述按照取件地址查询筛选的SQL语句，只不过相反而已，这里收件地址'表'需要约束查询，而取件地址'表'不用约束查询 SELECT orders.id, address_pick_up.address AS pick_up_address, address_recive.address AS recive_address, orders.order_number, orders.price, orders.service_fee_rate, orders.service_fee, orders.pay_amount, orders.real_price, orders.delivery_time, orders.cancel_time , orders.cancel_reson, orders.exceed_time, orders.gap, orders.create_time, orders.door_access, orders.user_id, orders.username, orders.phone, orders.status, orders.note, orders.image, category.image AS category_image, category.category_name, orders.deleted FROM tb_orders AS orders, tb_category AS category, (SELECT ad.id, CONCAT(school.school_name, ' ', compus.compus_name, ' ', build_category.name, ' ', building.building_name, ' ', ad.details) AS address FROM tb_address_book AS ad, tb_school AS school, tb_compus AS compus, tb_build_category AS build_category, tb_building AS building
ad.school_id = school.id AND ad.compus_id = compus.id AND ad.build_category_id = build_category.id AND ad.building_id = building.id AND ad.deleted = 0
) AS address_pick_up, -- 这是取件地址
(SELECT ad.id, CONCAT(school.school_name, ' ', compus.compus_name, ' ', build_category.name, ' ', building.building_name, ' ', ad.details) AS address FROM tb_address_book AS ad, tb_school AS school, tb_compus AS compus, tb_build_category AS build_category, tb_building AS building
ad.school_id = school.id AND ad.compus_id = compus.id AND ad.build_category_id = build_category.id AND ad.building_id = building.id AND ad.deleted = 0
and ad.id in
#{id}
) AS address_recive -- 这是收件地址
WHERE orders.deleted = 0 AND orders.status = 0 AND orders.category_id = category.id AND orders.pick_up_address = address_pick_up.id AND orders.recive_address = address_recive.id
AND orders.recive_address in
#{id}
ORDER BY orders.create_time desc

