select status
from tb_orders
where deleted = 0 AND id = #{id}

select * from tb_orders
where deleted = 0 AND
      order_number = #{orderNumber}

mapper.update:
update tb_orders
pick_up_address = #{pickUpAddress}, recive_address = #{reciveAddress}, order_number = #{orderNumber}, price = #{price}, service_fee_rate = #{serviceFeeRate}, service_fee = #{serviceFeeRate}, pay_amount = #{payAmount}, real_price = #{realPrice}, delivery_time = #{deliveryTime}, cancel_time = #{cancelTime}, cancel_reson = #{cancelReson}, exceed_time = #{exceedTime}, gap = #{gap}, create_time = #{createTime}, door_access = #{doorAccess}, user_id = #{userId}, username = #{username}, phone = #{phone}, status = #{status}, note = #{note}, image = #{image}, category_id = #{categoryId}, deleted = #{deleted},
where id = #{id}

update tb_orders
set status = #{status}
where order_number = #{orderNumber}

mapper.select:
SELECT o.id, o.order_number, o.status, c.category_name, o.price, o.service_fee, o.pay_amount, o.username, o.phone, o.note, o.door_access, o.create_time, o.cancel_time, o.cancel_reson AS cancel_reason, o.delivery_time, ap.address AS pick_up_address, ar.address AS recive_address, tk_user.realname AS taker_name, tk_user.phone AS taker_phone, tk.create_time AS take_order_time FROM tb_orders o LEFT JOIN tb_category c ON o.category_id = c.id LEFT JOIN ( SELECT ad.id, CONCAT(s.school_name, ' ', cp.compus_name, ' ', bc.name, ' ', b.building_name, ' ', ad.details) AS address FROM tb_address_book ad, tb_school s, tb_compus cp, tb_build_category bc, tb_building b WHERE ad.school_id = s.id AND ad.compus_id = cp.id AND ad.build_category_id = bc.id AND ad.building_id = b.id AND ad.deleted = 0 ) ap ON o.pick_up_address = ap.id LEFT JOIN ( SELECT ad.id, CONCAT(s.school_name, ' ', cp.compus_name, ' ', bc.name, ' ', b.building_name, ' ', ad.details) AS address FROM tb_address_book ad, tb_school s, tb_compus cp, tb_build_category bc, tb_building b WHERE ad.school_id = s.id AND ad.compus_id = cp.id AND ad.build_category_id = bc.id AND ad.building_id = b.id AND ad.deleted = 0 ) ar ON o.recive_address = ar.id LEFT JOIN tb_take_orders tk ON o.id = tk.order_id AND tk.deleted = 0 LEFT JOIN tb_user tk_user ON tk.user_id = tk_user.id WHERE o.deleted = 0 AND o.status IN
#{s}
ORDER BY o.create_time DESC LIMIT #{offset}, #{limit}

SELECT COALESCE(SUM(pay_amount), 0) FROM tb_orders
WHERE deleted = 0 AND pay_amount > 0
  AND create_time >= #{startTime} AND create_time <= #{endTime}

SELECT COALESCE(SUM(service_fee), 0) FROM tb_orders
WHERE deleted = 0 AND service_fee > 0
  AND create_time >= #{startTime} AND create_time <= #{endTime}
